<script setup>
import { computed, nextTick, ref } from 'vue';
import AccountExploreBanner from './AccountExploreBanner.vue';
import { Bold, ImagePlus, Italic, List, ArrowLeft, CalendarDays, CheckCircle2, ChevronLeft, ChevronRight, Heart, MapPin, MessageCircle, Plus, Search, Send, Star, Trash2, Users, X } from 'lucide-vue-next';
defineProps({ section: { type: String, required: true } });
const filter = ref('Semua');
const search = ref('');
const favorites = ref([{ id: 1, name: 'Open Trip Bali', type: 'Open Trip', place: 'Bali', price: 'Rp 750.000', image: '1537996194471-e657df975ab4' }, { id: 2, name: 'Private Trip Lombok', type: 'Private Trip', place: 'Lombok', price: 'Rp 1.500.000', image: '1518548419970-58e3b4079ab2' }]);
const visibleFavorites = computed(() => favorites.value.filter((item) => (filter.value === 'Semua' || item.type === filter.value) && item.name.toLowerCase().includes(search.value.toLowerCase())));
const travelers = ref([{ id: 1, name: 'Albnnaardy', relation: 'Diri sendiri' }]);
const travelerSearch = ref('');
const visibleTravelers = computed(() => travelers.value.filter((person) => person.name.toLowerCase().includes(travelerSearch.value.trim().toLowerCase())));
const travelerName = ref('');
const relation = ref('Keluarga');
const dialog = ref(null);
const editing = ref(null);
const openTraveler = (item = null) => { editing.value = item; travelerName.value = item?.name || ''; relation.value = item?.relation || 'Keluarga'; dialog.value.showModal(); };
const saveTraveler = () => { if (!travelerName.value.trim()) { return; } if (editing.value) { editing.value.name = travelerName.value.trim(); editing.value.relation = relation.value; } else { travelers.value.push({ id: Date.now(), name: travelerName.value.trim(), relation: relation.value }); } dialog.value.close(); };
const conversations = ref([{ id: 1, name: 'Partner Trip Bali', subtitle: 'Informasi perjalanan', messages: [{ own: false, text: 'Halo! Ada yang ingin ditanyakan tentang perjalananmu?' }] }, { id: 2, name: 'Tim TapakLokal', subtitle: 'Bantuan pemesanan', messages: [{ own: false, text: 'Selamat datang di pratinjau chat TapakLokal.' }] }]);
const selectedChat = ref(1);
const chat = computed(() => conversations.value.find((item) => item.id === selectedChat.value));
const draft = ref('');
const send = () => { if (!draft.value.trim()) { return; } chat.value.messages.push({ own: true, text: draft.value.trim() }); draft.value = ''; };
const rating = ref(0);
const reviewText = ref('');
const reviewEditor = ref(null);
const reviewImageInput = ref(null);
const reviewImages = ref([]);
const reviews = ref([]);
const reviewError = ref('');
const reviewView = ref('orders');
const reviewOrder = ref(null);
const reviewNotice = ref('');
const reviewPage = ref(1);
const reviewScroll = ref(null);
const reviewPageSize = 4;
const completedOrders = ref([
    { id: 'TL-2025-001', name: 'Pantai Drini', location: 'Gunungkidul, Yogyakarta', date: '24 Sep 2025', image: '1507525428034-b723cf961d3e', reviewed: false },
    { id: 'TL-2025-002', name: 'Open Trip Karimunjawa', location: 'Jepara, Jawa Tengah', date: '12 Agu 2025', image: '1518548419970-58e3b4079ab2', reviewed: false },
    { id: 'TL-2025-003', name: 'Candi Prambanan', location: 'Sleman, Yogyakarta', date: '30 Jul 2025', image: '1537996194471-e657df975ab4', reviewed: true },
    ...['Bromo Sunrise', 'Ranu Kumbolo', 'Pulau Pramuka', 'Kawah Ijen', 'Labuan Bajo', 'Dieng Plateau', 'Raja Ampat', 'Tanjung Lesung', 'Pulau Pari'].map((name, index) => ({
        id: `TL-2025-${String(index + 4).padStart(3, '0')}`,
        name: `Open Trip ${name}`,
        location: ['Probolinggo, Jawa Timur', 'Lumajang, Jawa Timur', 'Kepulauan Seribu', 'Banyuwangi, Jawa Timur', 'Nusa Tenggara Timur'][index % 5],
        date: `${20 - index} Jul 2025`,
        image: ['1500534314209-a25ddb2bd429', '1501179691627-eeaa65ea017c', '1518548419970-58e3b4079ab2', '1478827536114-da961b7e8b80', '1507525428034-b723cf961d3e'][index % 5],
        reviewed: index % 4 === 0,
    })),
]);
const reviewPageCount = computed(() => Math.max(1, Math.ceil(completedOrders.value.length / reviewPageSize)));
const reviewStart = computed(() => (reviewPage.value - 1) * reviewPageSize);
const visibleReviewOrders = computed(() => completedOrders.value.slice(reviewStart.value, reviewStart.value + reviewPageSize));
const goReviewPage = (page) => { reviewPage.value = Math.max(1, Math.min(page, reviewPageCount.value)); reviewScroll.value?.scrollTo({ top: 0, behavior: 'smooth' }); };
const openReview = (order) => {
    reviewOrder.value = order;
    rating.value = 0;
    reviewText.value = '';
    reviewImages.value = [];
    reviewError.value = '';
    reviewNotice.value = '';
    reviewView.value = 'form';
    nextTick(() => { if (reviewEditor.value) { reviewEditor.value.innerHTML = ''; } });
};
const formatReview = (command) => { reviewEditor.value?.focus(); document.execCommand(command, false); reviewText.value = reviewEditor.value?.innerText.trim() ?? ''; };
const updateReviewText = () => { reviewText.value = reviewEditor.value?.innerText.trim() ?? ''; };
const addReviewImages = (event) => {
    const files = Array.from(event.target.files ?? []);
    const valid = files.filter((file) => ['image/jpeg', 'image/png', 'image/webp'].includes(file.type) && file.size <= 2 * 1024 * 1024).slice(0, 5 - reviewImages.value.length);
    if (valid.length !== files.length) { reviewError.value = 'Foto harus JPG, PNG, atau WebP maksimal 2 MB. Maksimal 5 foto.'; }
    reviewImages.value.push(...valid.map((file) => ({ id: `${file.name}-${file.lastModified}`, url: URL.createObjectURL(file), name: file.name })));
    event.target.value = '';
};
const removeReviewImage = (image) => { reviewImages.value = reviewImages.value.filter((item) => item.id !== image.id); URL.revokeObjectURL(image.url); };
const saveReview = () => {
    if (!rating.value) { reviewError.value = 'Pilih rating terlebih dahulu.'; return; }
    if (reviewText.value.trim().length < 10) { reviewError.value = 'Tulis ulasan minimal 10 karakter.'; return; }
    reviews.value.unshift({ id: Date.now(), orderId: reviewOrder.value.id, orderName: reviewOrder.value.name, rating: rating.value, text: reviewText.value.trim(), images: reviewImages.value.map((image) => image.url) });
    reviewOrder.value.reviewed = true;
    reviewNotice.value = `Ulasan untuk ${reviewOrder.value.name} tersimpan pada pratinjau.`;
    reviewView.value = 'orders';
    rating.value = 0;
    reviewText.value = '';
    reviewImages.value = [];
    reviewError.value = '';
};
const subject = ref('');
const category = ref('Pemesanan');
const helpText = ref('');
const tickets = ref([]);
const saveTicket = () => {
    if (!subject.value.trim() || helpText.value.trim().length < 10) { return; }
    tickets.value.unshift({ id: Date.now(), subject: subject.value.trim(), category: category.value, text: helpText.value.trim(), date: 'Baru saja' });
    subject.value = '';
    helpText.value = '';
};
const control = 'w-full rounded-xl border border-[#dce5f0] bg-white px-3 py-3 text-sm outline-[#078cff]';
const primary = 'rounded-lg bg-[#1045a5] px-4 py-2.5 text-xs font-semibold text-white transition hover:bg-[#083788] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#078cff]';
</script>

