                    <footer class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-4 py-3"><p class="text-[10px] text-slate-500" aria-live="polite">Menampilkan {{ reviewStart + 1 }}–{{ Math.min(reviewStart + reviewPageSize, completedOrders.length) }} dari {{ completedOrders.length }} pesanan</p><nav aria-label="Halaman pesanan untuk ulasan" class="flex items-center gap-1"><button type="button" aria-label="Halaman sebelumnya" :disabled="reviewPage === 1" class="grid size-8 place-items-center rounded-full text-[#3E7BEF] hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-30" @click="goReviewPage(reviewPage - 1)"><ChevronLeft class="size-4" /></button><button v-for="number in reviewPageCount" :key="number" type="button" :aria-label="`Halaman ${number}`" :aria-current="reviewPage === number ? 'page' : undefined" class="grid size-8 place-items-center rounded-full text-xs font-semibold transition-colors" :class="reviewPage === number ? 'bg-[#3E7BEF] text-white shadow-[0_3px_9px_rgba(62,123,239,0.22)]' : 'text-slate-500 hover:bg-blue-50 hover:text-[#3E7BEF]'" @click="goReviewPage(number)">{{ number }}</button><button type="button" aria-label="Halaman berikutnya" :disabled="reviewPage === reviewPageCount" class="grid size-8 place-items-center rounded-full text-[#3E7BEF] hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-30" @click="goReviewPage(reviewPage + 1)"><ChevronRight class="size-4" /></button></nav></footer>
                </section>
                <section v-if="reviews.length" class="mt-4 overflow-hidden rounded-2xl border border-[#e1eaf5] bg-white shadow-[0_4px_20px_rgba(23,75,120,0.04)]"><div class="border-b border-slate-100 px-4 py-3 text-xs font-semibold text-[#183660]">Ulasan saya</div><div class="space-y-3 bg-[#f8fafc] p-3 sm:p-4"><article v-for="review in reviews" :key="review.id" class="rounded-xl border border-[#e1eaf5] bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h4 class="text-xs font-bold text-[#183660]">{{ review.orderName }}</h4><span class="inline-flex items-center gap-1 text-[10px] font-semibold text-amber-600"><Star class="size-3.5 fill-amber-400 text-amber-400" />{{ review.rating }} / 5</span></div><p class="mt-2 whitespace-pre-wrap break-words text-[11px] leading-5 text-slate-600">{{ review.text }}</p><span class="mt-2 block text-[9px] text-slate-400">Pratinjau · Belum dipublikasikan</span></article></div></section>
            </template>
            <form v-else class="mt-4 overflow-hidden rounded-2xl border border-[#e1eaf5] bg-white shadow-[0_4px_20px_rgba(23,75,120,0.04)]" @submit.prevent="saveReview">
                <div class="flex items-center gap-3 border-b border-slate-100 px-4 py-3"><button type="button" class="grid size-8 place-items-center rounded-lg text-[#3E7BEF] hover:bg-[#edf4ff]" aria-label="Kembali ke pesanan" @click="reviewView = 'orders'"><ArrowLeft class="size-4" /></button><div><h3 class="text-xs font-semibold text-[#183660]">Beri ulasan</h3><p class="mt-0.5 text-[10px] text-slate-500">Bagikan pengalaman perjalananmu.</p></div></div>
                <div class="space-y-5 p-4 sm:p-5">
                    <div class="flex gap-3 rounded-xl border border-[#e1eaf5] bg-[#f8fafc] p-3"><img :src="`https://images.unsplash.com/photo-${reviewOrder.image}?auto=format&fit=crop&w=240&q=85`" :alt="reviewOrder.name" class="size-14 rounded-lg object-cover" /><div><h4 class="text-xs font-bold text-[#183660]">{{ reviewOrder.name }}</h4><p class="mt-1 text-[10px] text-slate-500">{{ reviewOrder.location }}</p><p class="mt-1 text-[9px] text-slate-400">{{ reviewOrder.date }}</p></div></div>
                    <fieldset><legend class="text-xs font-semibold text-[#183660]">Bagaimana pengalamanmu?</legend><div class="mt-3 flex gap-2"><button v-for="value in 5" :key="value" type="button" class="grid size-10 place-items-center rounded-xl border transition-colors focus-visible:outline-2 focus-visible:outline-[#3E7BEF]" :class="value <= rating ? 'border-amber-200 bg-amber-50 text-amber-500' : 'border-[#e1eaf5] bg-white text-slate-300 hover:bg-[#f8fafc]'" :aria-label="`Rating ${value} dari 5`" :aria-pressed="rating === value" @click="rating = value"><Star class="size-5" :class="value <= rating ? 'fill-current' : ''" /></button></div></fieldset>
                    <div><div class="mb-2 flex items-center justify-between gap-3"><label for="review-editor" class="text-xs font-semibold text-[#183660]">Ceritakan pengalamanmu</label><span class="text-[9px] text-slate-400">Minimal 10 karakter</span></div><div class="overflow-hidden rounded-xl border border-[#e1eaf5] bg-white focus-within:border-[#9fc8fb] focus-within:ring-2 focus-within:ring-blue-50"><div class="flex items-center gap-1 border-b border-slate-100 bg-[#fbfdff] px-2 py-1.5"><button type="button" class="grid size-7 place-items-center rounded-md text-[#597494] hover:bg-[#edf4ff] hover:text-[#3E7BEF]" aria-label="Tebal" title="Tebal" @click="formatReview('bold')"><Bold class="size-3.5" /></button><button type="button" class="grid size-7 place-items-center rounded-md text-[#597494] hover:bg-[#edf4ff] hover:text-[#3E7BEF]" aria-label="Miring" title="Miring" @click="formatReview('italic')"><Italic class="size-3.5" /></button><button type="button" class="grid size-7 place-items-center rounded-md text-[#597494] hover:bg-[#edf4ff] hover:text-[#3E7BEF]" aria-label="Daftar poin" title="Daftar poin" @click="formatReview('insertUnorderedList')"><List class="size-3.5" /></button><span class="mx-1 h-5 w-px bg-slate-200"></span><input ref="reviewImageInput" type="file" accept="image/jpeg,image/png,image/webp" multiple class="hidden" @change="addReviewImages" /><button type="button" :disabled="reviewImages.length === 5" class="inline-flex min-h-7 items-center gap-1 rounded-md px-2 text-[9px] font-semibold text-[#3E7BEF] hover:bg-[#edf4ff] disabled:cursor-not-allowed disabled:opacity-40" @click="reviewImageInput.click()"><ImagePlus class="size-3.5" />Tambah foto</button></div><div id="review-editor" ref="reviewEditor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Isi ulasan" data-placeholder="Apa yang paling berkesan dari perjalanan ini?" class="min-h-32 px-3 py-3 text-xs leading-5 text-slate-700 outline-none empty:before:pointer-events-none empty:before:content-[attr(data-placeholder)] empty:before:text-slate-400" @input="updateReviewText" @blur="updateReviewText"></div></div><div v-if="reviewImages.length" class="mt-3 flex flex-wrap gap-2"><div v-for="image in reviewImages" :key="image.id" class="group relative size-20 overflow-hidden rounded-lg border border-[#e1eaf5]"><img :src="image.url" :alt="image.name" class="size-full object-cover" /><button type="button" :aria-label="`Hapus foto ${image.name}`" class="absolute right-1 top-1 grid size-6 place-items-center rounded-full bg-slate-900/65 text-white opacity-0 transition-opacity group-hover:opacity-100 focus-visible:opacity-100" @click="removeReviewImage(image)"><Trash2 class="size-3" /></button></div></div><p class="mt-2 text-[9px] leading-4 text-slate-400">Tambahkan maksimal 5 foto JPG, PNG, atau WebP. Maksimal 2 MB per foto.</p></div>
                    <p v-if="reviewError" role="alert" class="text-[11px] text-rose-600">{{ reviewError }}</p>
                </div>
                <div class="flex justify-end gap-2 border-t border-slate-100 bg-[#fbfcfe] px-4 py-3"><button type="button" class="min-h-9 rounded-lg border border-[#e1eaf5] bg-white px-4 text-[10px] font-semibold text-slate-600 hover:bg-slate-50" @click="reviewView = 'orders'">Batal</button><button class="min-h-9 rounded-lg bg-[#078cff] px-4 text-[10px] font-semibold text-white hover:bg-[#0878db]">Kirim ulasan</button></div>
            </form>
            <AccountExploreBanner />
        </template>

        <template v-else-if="section === 'Pesan Bantuan'">
            <section class="mt-4 rounded-2xl border border-[#c7e5f5] bg-gradient-to-r from-[#edf5ff] via-white to-[#e7f8f7] p-4 sm:p-5"><div class="flex flex-wrap items-center justify-between gap-4"><div class="flex items-start gap-3"><span class="grid size-11 shrink-0 place-items-center rounded-xl bg-[#3E7BEF] text-white shadow-[0_4px_12px_rgba(62,123,239,0.2)]"><MessageCircle class="size-5" /></span><div><h3 class="text-sm font-bold text-[#183660]">Butuh bantuan perjalanan?</h3><p class="mt-1 max-w-md text-[11px] leading-5 text-slate-500">Pilih topik, tuliskan kendala, dan simpan pesanmu untuk ditinjau.</p></div></div><span class="rounded-full border border-blue-100 bg-white/85 px-2.5 py-1 text-[10px] font-semibold text-[#3E7BEF]">Pusat bantuan</span></div></section>
            <div class="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_220px]">
                <form class="overflow-hidden rounded-2xl border border-[#e1eaf5] bg-white shadow-[0_4px_20px_rgba(23,75,120,0.04)]" @submit.prevent="saveTicket"><div class="border-b border-slate-100 px-4 py-3"><h3 class="text-xs font-semibold text-[#183660]">Kirim pesan bantuan</h3><p class="mt-1 text-[10px] text-slate-500">Jangan sertakan kata sandi atau data pembayaran sensitif.</p></div><div class="space-y-4 p-4 sm:p-5"><fieldset><legend class="text-xs font-semibold text-[#183660]">Pilih topik</legend><div class="mt-2 flex flex-wrap gap-2"><button v-for="item in ['Pemesanan', 'Pembayaran', 'Voucher & Points', 'Akun', 'Lainnya']" :key="item" type="button" class="min-h-8 rounded-full border px-3 text-[10px] font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-[#3E7BEF]" :class="category === item ? 'border-[#3E7BEF] bg-[#3E7BEF] text-white shadow-sm' : 'border-[#e1eaf5] bg-white text-slate-500 hover:bg-[#edf4ff] hover:text-[#3E7BEF]'" @click="category = item">{{ item }}</button></div></fieldset><label class="flex flex-col gap-2 text-xs font-semibold text-[#183660]">Judul pesan<input v-model="subject" required maxlength="120" placeholder="Ringkasan kendalamu" class="h-10 rounded-xl border border-[#e1eaf5] px-3 text-xs font-normal outline-[#078cff] focus:border-[#9fc8fb]" /></label><label class="flex flex-col gap-2 text-xs font-semibold text-[#183660]">Detail kendala<textarea v-model="helpText" required minlength="10" maxlength="3000" rows="5" placeholder="Jelaskan kendala agar kami dapat memahami situasinya." class="resize-y rounded-xl border border-[#e1eaf5] px-3 py-3 text-xs font-normal leading-5 outline-[#078cff] focus:border-[#9fc8fb]"></textarea><span class="text-[9px] font-normal text-slate-400">{{ helpText.length }} / 3000 karakter</span></label></div><div class="flex justify-end gap-2 border-t border-slate-100 bg-[#fbfcfe] px-4 py-3"><button type="button" class="min-h-9 rounded-lg border border-[#e1eaf5] bg-white px-4 text-[10px] font-semibold text-slate-600 hover:bg-slate-50" @click="subject = ''; helpText = ''">Bersihkan</button><button class="min-h-9 rounded-lg bg-[#078cff] px-4 text-[10px] font-semibold text-white hover:bg-[#0878db]">Kirim pesan</button></div></form>
                <aside class="relative isolate flex min-h-full flex-col overflow-hidden rounded-2xl border border-[#c7e5f5] bg-gradient-to-b from-[#edf5ff] via-white to-[#e8f8f7] shadow-[0_4px_20px_rgba(23,75,120,0.04)]"><div aria-hidden="true" class="absolute -right-12 -top-10 -z-10 size-40 rounded-full border-[24px] border-white/70"></div><div class="border-b border-white/80 px-4 py-4"><div class="flex items-center gap-2"><span class="grid size-8 place-items-center rounded-lg bg-white text-[#3E7BEF] shadow-sm"><MessageCircle class="size-4" /></span><div><h3 class="text-xs font-semibold text-[#183660]">Sebelum mengirim</h3><p class="mt-0.5 text-[9px] text-slate-500">Buat pesanmu lebih mudah dipahami.</p></div></div></div><div class="relative space-y-4 p-4"><div class="absolute bottom-8 left-[29px] top-8 w-px bg-[#cfe2fb]"></div><div class="relative flex gap-3"><span class="grid size-8 shrink-0 place-items-center rounded-full border border-blue-100 bg-white text-[11px] font-semibold text-[#3E7BEF]">1</span><div><p class="text-[10px] font-semibold text-[#183660]">Pilih topik yang tepat</p><p class="mt-1 text-[10px] leading-5 text-slate-500">Agar pesanmu masuk ke kategori bantuan yang sesuai.</p></div></div><div class="relative flex gap-3"><span class="grid size-8 shrink-0 place-items-center rounded-full border border-blue-100 bg-white text-[11px] font-semibold text-[#3E7BEF]">2</span><div><p class="text-[10px] font-semibold text-[#183660]">Tulis detail pesanan</p><p class="mt-1 text-[10px] leading-5 text-slate-500">Sertakan kode pesanan atau transaksi jika berkaitan.</p></div></div><div class="relative flex gap-3"><span class="grid size-8 shrink-0 place-items-center rounded-full border border-blue-100 bg-white text-[11px] font-semibold text-[#3E7BEF]">3</span><div><p class="text-[10px] font-semibold text-[#183660]">Jaga data pribadimu</p><p class="mt-1 text-[10px] leading-5 text-slate-500">Jangan kirim kata sandi, PIN, atau kode OTP.</p></div></div></div><div class="mt-auto border-t border-white/80 bg-white/60 p-4"><div class="rounded-xl border border-white bg-white/80 p-3"><p class="text-[10px] font-semibold text-[#183660]">Perlu bantuan cepat?</p><p class="mt-1 text-[9px] leading-4 text-slate-500">Cek riwayat transaksi atau pesananmu untuk menemukan informasi yang diperlukan.</p></div></div></aside>
            </div>
            <section v-if="tickets.length" class="mt-4 overflow-hidden rounded-2xl border border-[#e1eaf5] bg-white shadow-[0_4px_20px_rgba(23,75,120,0.04)]"><div class="flex items-center justify-between border-b border-slate-100 px-4 py-3"><h3 class="text-xs font-semibold text-[#183660]">Pesan bantuan tersimpan</h3><span class="rounded-full bg-[#edf4ff] px-2.5 py-1 text-[10px] text-[#3E7BEF]">{{ tickets.length }} pesan</span></div><div class="space-y-3 bg-[#f8fafc] p-3 sm:p-4"><article v-for="ticket in tickets" :key="ticket.id" class="rounded-xl border border-[#e1eaf5] bg-white p-4"><div class="flex flex-wrap items-center justify-between gap-2"><span class="rounded-full bg-[#edf4ff] px-2 py-0.5 text-[9px] font-semibold text-[#3E7BEF]">{{ ticket.category }}</span><span class="text-[9px] text-slate-400">{{ ticket.date }}</span></div><h4 class="mt-2 text-xs font-bold text-[#183660]">{{ ticket.subject }}</h4><p class="mt-2 whitespace-pre-wrap break-words text-[11px] leading-5 text-slate-600">{{ ticket.text }}</p><span class="mt-3 inline-flex rounded-full bg-amber-50 px-2 py-1 text-[9px] font-medium text-amber-700">Draf lokal</span></article></div></section>
            <AccountExploreBanner />
        </template>
        <p class="mt-4 text-[10px] leading-5 text-slate-400">Pratinjau lokal · Data contoh dan perubahan tidak disimpan ke server. Chat, ulasan, dan bantuan tidak dikirim kepada pihak lain.</p>
        <dialog ref="dialog" class="fixed inset-0 m-auto w-[calc(100%-2rem)] max-w-md rounded-2xl bg-white p-6 text-slate-700 backdrop:bg-slate-900/50" aria-labelledby="traveler-dialog"><form class="space-y-4" @submit.prevent="saveTraveler"><div class="flex justify-between"><h2 id="traveler-dialog" class="font-bold">{{ editing ? 'Edit' : 'Tambah' }} wisatawan</h2><button type="button" aria-label="Tutup" @click="dialog.close()"><X class="size-5" /></button></div><label class="flex flex-col gap-2 text-xs">Nama lengkap<input v-model="travelerName" autofocus required maxlength="100" :class="control" /></label><label class="flex flex-col gap-2 text-xs">Hubungan<select v-model="relation" :class="control"><option>Diri sendiri</option><option>Keluarga</option><option>Teman</option><option>Lainnya</option></select></label><button :disabled="!travelerName.trim()" class="min-h-10 w-full rounded-xl bg-[#078cff] px-4 text-xs font-semibold text-white hover:bg-[#0878db] disabled:cursor-not-allowed disabled:opacity-40">Simpan wisatawan</button></form></dialog>
    </section>
</template>
